// Transformation in FIWARE Smart Data Model "WeatherObserved"
const now = new Date().toISOString();
msg.payload = [{
    id: 'urn:ngsi-ld:WeatherObserved:demo-station-1',
    type: 'WeatherObserved',
    dateObserved: { type: 'Property', value: { '@type': 'DateTime', '@value': now } },
    temperature: { type: 'Property', value: 18 + Math.round(Math.random() * 60) / 10, unitCode: 'CEL' },
    relativeHumidity: { type: 'Property', value: Math.round(40 + Math.random() * 50) / 100 },
    location: { type: 'GeoProperty', value: { type: 'Point', coordinates: [8.5010, 50.5658] } },
    '@context': 'https://uri.etsi.org/ngsi-ld/v1/ngsi-ld-core-context-v1.6.jsonld'
}];
msg.headers = { 'Content-Type': 'application/ld+json' };
return msg;
